function ESP.step()
    local want = ESP.list()
    for c in pairs(ESP.items) do if not want[c] or not c.Parent then ESP.clear(c) end end
    local me = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
    local col = ESP.col("esp_color", Color3.fromRGB(255, 75, 75))
    for c in pairs(want) do
        local head = c:FindFirstChild("Head")
        local it = ESP.items[c]
        if not it and head then it = ESP.build(c, head) ESP.items[c] = it end
        if it then
            local hum = c:FindFirstChildOfClass("Humanoid")
            local hp, mx = hum and hum.Health or 0, hum and math.max(hum.MaxHealth, 1) or 100
            local pl = Players:GetPlayerFromCharacter(c)
            local tool = c:FindFirstChildOfClass("Tool")
            local d = (me and head) and math.floor((head.Position - me.Position).Magnitude) or 0
