function ESP.tracers()
    if not Drawing then return end
    local cam = Workspace.CurrentCamera
    local vp = cam.ViewportSize
    local show = on("esp_on") and on("trc_on")
    local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
    local inMatch = (lp:GetAttribute("MatchId") or "") ~= ""
    if not hum or hum.Health <= 0 or (inMatch and lp:GetAttribute("Alive") == false) then show = false end
    local from = val("trc_from", "Bottom")
    local o = from == "Center" and Vector2.new(vp.X / 2, vp.Y / 2) or (from == "Top" and Vector2.new(vp.X / 2, 0) or Vector2.new(vp.X / 2, vp.Y))
    local col = ESP.col("trc_color", Color3.fromRGB(255, 75, 75))
    local th = tonumber(val("trc_thick", 1.5)) or 1.5
    for c, ln in pairs(ESP.lines) do if not ESP.items[c] then pcall(function() ln:Remove() end) ESP.lines[c] = nil end end
    for c in pairs(ESP.items) do
        local r = c:FindFirstChild("HumanoidRootPart")
        local ln = ESP.lines[c]
        if not ln then
            local ok, l = pcall(Drawing.new, "Line")
            if ok then ln = l ESP.lines[c] = l end
        end
        if ln then
            local vis = false
            if show and r then
                local sp, onScreen = cam:WorldToViewportPoint(r.Position - Vector3.new(0, 2.5, 0))
                if onScreen and sp.Z > 0 then
                    ln.From, ln.To = o, Vector2.new(sp.X, sp.Y)
                    vis = true
                end
            end
            ln.Visible = vis
            ln.Color, ln.Thickness, ln.Transparency = col, th, 0.9
        end
    end
end
