notify = function(text) pcall(function() Library:Notify({ Title = "COMBO_WICK", Description = text, Time = 4 }) end) end
local function section(name, fn)
    local ok = xpcall(fn, debug.traceback)
    if not ok then notify(name .. " tab failed to load") end
end

section("Suggestions", function()
    local Tab = Window:AddTab("Suggestions", "message-square")
    local FEEDBACK_URL = "https://v0-secure-discord-proxy.vercel.app/api/v2sender"
    local _request = request or (syn and syn.request) or http_request
    local okId, cid = pcall(function() return gethwid and gethwid() end)
    local HWID = (okId and type(cid) == "string" and cid ~= "") and cid or tostring(lp.UserId)
    local ERR = { empty = "The message is empty.", no_links = "Links are not allowed.", too_long = "Too long (500 max).", network = "Network error.", no_request = "Your executor cannot send requests.", bad_response = "Unexpected server response.", unreachable = "Your executor cannot reach the server." }
    local function send(ftype, msg)
        if not _request then return false, "no_request" end
        local ok, res = pcall(function()
            return _request({ Url = FEEDBACK_URL, Method = "POST", Headers = { ["Content-Type"] = "application/json" }, Body = HttpService:JSONEncode({ type = ftype, message = msg, hwid = HWID, placeId = tostring(game.PlaceId), username = lp.Name, version = CONFIG.VERSION }) })
        end)
        if not ok or type(res) ~= "table" then return false, (type(res) == "string") and "unreachable" or "network" end
        local code = res.StatusCode or res.status_code or res.Status or res.status
        if type(code) == "number" and code ~= 200 and code ~= 201 and code ~= 204 then return false, "http_" .. code end
        local dok, data = pcall(function() return HttpService:JSONDecode(res.Body or res.body or "") end)
        if not dok or type(data) ~= "table" then return false, "bad_response" end
        if data.success == true then return true end
        return false, tostring(data.error or "unknown")
    end
    local FG = Tab:AddLeftGroupbox("Suggestions / Help", "message-square")
    FG:AddDropdown("FeedbackType", { Text = "Type", Values = { "Suggestion", "Bug", "Help" }, Default = "Suggestion", Tooltip = "What your message is about" })
    FG:AddInput("FeedbackMsg", { Default = "", Numeric = false, Finished = false, ClearTextOnFocus = false, Text = "Message", Placeholder = "500 chars max, no links", Tooltip = "Your message to the dev" })
    local status = FG:AddLabel("", true)
    local last = 0
    FG:AddButton({ Text = "Send", Tooltip = "Send your message", Func = function()
        if tick() - last < 20 then setText(status, string.format("Wait %ds", math.ceil(20 - (tick() - last)))) return end
        local msg = tostring(val("FeedbackMsg", "")):gsub("^%s*(.-)%s*$", "%1")
        if msg == "" then setText(status, ERR.empty) return end
        if #msg > 500 then setText(status, ERR.too_long) return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then setText(status, ERR.no_links) return end
        setText(status, "Sending...")
        task.spawn(function()
            local ok, err = send(tostring(val("FeedbackType", "Suggestion")):lower(), msg)
            if ok then last = tick() setText(status, "Sent. Thank you!") pcall(function() Opt.FeedbackMsg:SetValue("") end)
            else setText(status, ERR[err] or ("Failed: " .. tostring(err))) end
        end)
    end })
    FG:AddLabel("Max 3 messages per hour.", true)

    local HG = Tab:AddLeftGroupbox("Quick Start", "life-buoy")
    HG:AddLabel("<b>Aim</b>  Combat > Silent Aim", true)
    HG:AddLabel("Keep enemies inside the circle.", true)
    HG:AddLabel("Bows: hold to draw, release.", true)
    HG:AddLabel("<b>See</b>  Visuals > ESP", true)

    local CG = Tab:AddRightGroupbox("Changelog", "list")
    CG:AddLabel('<font color="#f5c542"><b>2026-10-27 · v1.1</b></font>', true)
    for _, l in ipairs({ "ESP outline", "Health bars", "Tracers", "ESP colors", "Max distance", "Wall check fix", "Cleaner layout" }) do CG:AddLabel("• " .. l, true) end
    CG:AddLabel('<font color="#f5c542"><b>2026-10-27 · v1.0</b></font>', true)
    for _, l in ipairs({ "First release", "Silent aim", "Real arrow drop", "Moving target lead", "Bows, guns, knives", "Head or body", "Replay safe", "Re-runs after hop", "FOV circle", "Enemy ESP" }) do CG:AddLabel("• " .. l, true) end
end)

